/* Nano Motion: static storefront demo; pixel identity is handled in pixel-user.js. */
const $ = (s, root = document) => root.querySelector(s);
const escapeHTML = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money = n => new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(n);
const read = (key, fallback) => {try{return JSON.parse(localStorage.getItem(key)) ?? fallback;}catch{return fallback;}};
const save = (key, value) => {try{localStorage.setItem(key,JSON.stringify(value));}catch{toast('Browser storage is unavailable. Your changes last for this visit.');}};
const rawCart = read('nm_cart',[]);
let cart = Array.isArray(rawCart) ? rawCart.filter(x=>PRODUCTS.some(p=>p.id===x.id&&p.sizes.includes(x.size))&&Number.isInteger(x.qty)&&x.qty>0&&x.qty<=99):[];
let currentUser = read('nm_session',null), selectedSize = '', latestOrder = read('nm_last_order',null);
let registration = false;
const icon = name => `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${({search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',user:'<circle cx="12" cy="8" r="3.5"/><path d="M5 21v-2a7 7 0 0 1 14 0v2"/>',bag:'<path d="M5 7h14l1 14H4L5 7Z"/><path d="M8 8V6a4 4 0 0 1 8 0v2"/>',truck:'<path d="M2 5h12v12H2zM14 9h4l4 4v4h-8"/><circle cx="6" cy="18" r="2"/><circle cx="18" cy="18" r="2"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',check:'<path d="m5 12 4 4L19 6"/>',return:'<path d="m7 3-4 4 4 4M3 7h11a7 7 0 0 1 0 14h-3"/>'})[name]||''}</svg>`;
const url = (page,params={}) => {const p=new URLSearchParams({page,...params});return `?${p.toString()}`;};
function captureURL(){const params = new URLSearchParams(location.search);const all=Object.create(null);for(const [k,v] of params){if(!Object.hasOwn(all,k))all[k]=[];all[k].push(v);}window.NanoMotion = {...window.NanoMotion,urlParams:all,getParam:(key)=>new URLSearchParams(location.search).get(key),getAllParams:(key)=>new URLSearchParams(location.search).getAll(key)};try{sessionStorage.setItem('nm_url_params',JSON.stringify(all));}catch{}window.dispatchEvent(new CustomEvent('nanomotion:urlchange',{detail:all}));return params;}
function navigate(href){history.pushState({},'',href);selectedSize='';render(true,true);window.scrollTo(0,0);}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3200);}
function header(params){return `<div class="announcement">A LITTLE MORE MOTION. &nbsp; FREE SHIPPING ON ORDERS $75+</div><header class="header"><a class="brand" href="?page=home" aria-label="Nano Motion home"><span class="mark">N</span><span>NANO<br>MOTION</span></a><form class="search" id="search-form" role="search"><input type="search" name="q" placeholder="Find your next essential" aria-label="Search products" value="${escapeHTML(params.get('q')||'')}"><button class="icon-button" aria-label="Search">${icon('search')}</button></form><div class="header-actions"><a class="icon-button" href="?page=account" aria-label="Member account">${icon('user')}<span class="label">${currentUser?escapeHTML(currentUser.firstName):'Account'}</span></a><a class="icon-button" href="?page=cart" aria-label="Shopping bag, ${cart.reduce((a,b)=>a+b.qty,0)} items">${icon('bag')}<span class="count">${cart.reduce((a,b)=>a+b.qty,0)}</span></a></div></header><nav class="nav" aria-label="Product categories">${CATEGORIES.map(c=>`<a class="${params.get('category')===c?'active':''}" href="${url('shop',{category:c})}">${c}</a>`).join('')}</nav>`;}
function footer(){return `<footer class="footer"><div class="footer-top"><div><a class="brand" href="?page=home"><span class="mark">N</span><span>NANO<br>MOTION</span></a><p>For every way you move.</p></div><div class="footer-links"><a href="?page=shop">Shop all</a><a href="?page=account">Motion Club</a><a href="?page=cart">Your bag</a></div></div><div class="footer-bottom"><span>© ${new Date().getFullYear()} Nano Motion</span><span>United States · USD $</span><span>Demo store — no real purchases</span></div></footer>`;}
function card(p){return `<a class="product" href="${url('product',{id:p.id})}"><div class="product-media">${p.badge?`<span class="badge">${p.badge}</span>`:''}<img src="${p.image}" alt="${escapeHTML(p.name)} — representative demo image" loading="lazy" width="500" height="625"></div><div class="product-meta"><h3>${p.name}</h3><span class="price">${money(p.price)}</span></div><p>${p.category} · ${p.color}</p><div class="swatches" aria-hidden="true"><i></i></div></a>`;}
function home(){return `<main><section class="hero"><img src="assets/hero.jpg" alt="Runner moving across an open landscape" fetchpriority="high"><div class="hero-content"><div class="eyebrow">Less limits. More motion.</div><h1>MADE TO<br>MOVE YOU.</h1><p>Performance essentials for the miles, the reps, and everything in between.</p><a class="button lime" href="?page=shop">Find your motion ${icon('arrow')}</a></div><div class="hero-index">01 — EVERYDAY PERFORMANCE</div></section><div class="benefits"><span>${icon('truck')} Free shipping over $75</span><span>${icon('return')} 30-day easy returns</span><span>${icon('check')} Built for everyday movement</span></div><section class="section"><div class="section-head"><h2>YOUR MOVE. YOUR GEAR.</h2><a class="text-link" href="?page=shop">Explore all →</a></div><div class="category-grid">${CATEGORIES.map((c,i)=>`<a class="category" href="${url('shop',{category:c})}"><img src="${[IMAGE.shoe,IMAGE.shorts,IMAGE.shirt,IMAGE.leggings,IMAGE.bag,IMAGE.mat][i]}" alt="${c}" loading="lazy"><span>${c}<b aria-hidden="true">↗</b></span></a>`).join('')}</div></section><section class="section" style="padding-top:10px"><div class="section-head"><div><div class="eyebrow">Tested by movement. Loved for a reason.</div><h2>IN YOUR ROTATION.</h2></div><a class="text-link" href="?page=shop">Shop all →</a></div><div class="products">${['stride-runner','form-tee','power-short','flow-legging'].map(id=>card(PRODUCTS.find(p=>p.id===id))).join('')}</div></section><section class="club-banner"><div><div class="eyebrow">The Motion Club</div><h2>GOOD THINGS COME TO MOVERS.</h2><p>Join the club. Keep your details ready for your next move.</p></div><a class="button" href="?page=account&mode=register">Join the movement ${icon('arrow')}</a></section></main>`;}
function shop(params){const category=params.get('category')||'', q=(params.get('q')||'').trim(),sort=params.get('sort')||'featured',size=params.get('size')||'';let items=PRODUCTS.filter(p=>(!category||p.category===category)&&(!q||`${p.name} ${p.category} ${p.description} ${p.color}`.toLowerCase().includes(q.toLowerCase()))&&(!size||p.sizes.includes(size)));if(sort==='low')items.sort((a,b)=>a.price-b.price);if(sort==='high')items.sort((a,b)=>b.price-a.price);if(sort==='name')items.sort((a,b)=>a.name.localeCompare(b.name));return `<main class="page"><div class="breadcrumb"><a href="?page=home">Home</a> / Shop</div><div class="catalog-head"><div><div class="eyebrow">Find your next essential</div><h1>${q?`RESULTS FOR “${escapeHTML(q)}”`:escapeHTML(category||'ALL IN MOTION.')}</h1><p class="muted">${items.length} ${items.length===1?'essential':'essentials'} for the way you move.</p></div></div><div class="filters"><select id="category-filter" aria-label="Filter by category"><option value="">All categories</option>${CATEGORIES.map(c=>`<option ${c===category?'selected':''}>${c}</option>`).join('')}</select><select id="size-filter" aria-label="Filter by size"><option value="">All sizes</option>${['XS','S','M','L','XL','XXL','7','8','9','10','11','12','One size'].map(s=>`<option ${s===size?'selected':''}>${s}</option>`).join('')}</select><select id="sort-filter" aria-label="Sort products">${[['featured','Featured'],['low','Price: low to high'],['high','Price: high to low'],['name','Name: A to Z']].map(([v,t])=>`<option value="${v}" ${sort===v?'selected':''}>${t}</option>`).join('')}</select>${category||q||size?'<a class="button outline" href="?page=shop">Clear filters</a>':''}</div>${items.length?`<div class="products">${items.map(card).join('')}</div>`:'<div class="empty"><h2>NO MATCH THIS TIME.</h2><p>Try another search or explore all our essentials.</p><a class="button" href="?page=shop">Shop all products</a></div>'}</main>`;}
function product(params){const p=PRODUCTS.find(x=>x.id===params.get('id'));if(!p)return `<main class="page empty"><h1>PRODUCT NOT FOUND.</h1><a class="button" href="?page=shop">Back to shop</a></main>`;if(p.sizes.length===1)selectedSize=p.sizes[0];return `<main class="page"><div class="breadcrumb"><a href="?page=home">Home</a> / <a href="${url('shop',{category:p.category})}">${p.category}</a> / ${p.name}</div><div class="details"><div class="detail-image"><img src="${p.image}" alt="${p.name} — representative demo image"></div><section class="detail-copy"><div class="eyebrow">${p.category}</div><h1>${p.name}</h1><div class="detail-price">${money(p.price)}</div><p class="muted">${p.description}</p><p><strong>Color:</strong> ${p.color}</p><label id="size-label"><strong>${p.category==='Running gear'&&p.id==='stride-runner'?'US shoe size':'Size'}</strong> <span id="size-value">${selectedSize}</span></label><div class="sizes" role="group" aria-labelledby="size-label">${p.sizes.map(s=>`<button type="button" class="size ${selectedSize===s?'selected':''}" data-size="${s}" aria-pressed="${selectedSize===s}">${s}</button>`).join('')}</div><p id="size-error" class="error" role="alert"></p><label class="field">Quantity<select id="product-qty">${[1,2,3,4,5].map(n=>`<option>${n}</option>`).join('')}</select></label><div class="buy-actions"><button class="button lime" data-add="${p.id}">Add to bag ${icon('bag')}</button><button class="button outline" data-buy="${p.id}">Buy now</button></div><div class="facts"><p>${icon('truck')} Free shipping on orders $75+</p><p>Standard delivery: 3–5 business days</p><p>30-day returns · Demo policy</p><p class="muted small">Mock product. Photography is representative; styles and colors may differ.</p></div></section></div><section class="section" style="padding-left:0;padding-right:0"><div class="section-head"><h2>KEEP THE MOMENTUM.</h2></div><div class="products">${PRODUCTS.filter(x=>x.category===p.category&&x.id!==p.id).map(card).join('')}</div></section></main>`;}
function totals(items){const subtotal=items.reduce((s,x)=>s+PRODUCTS.find(p=>p.id===x.id).price*x.qty,0),shipping=subtotal>=75||subtotal===0?0:7;return {subtotal,shipping,total:subtotal+shipping};}
function summary(items,checkout=false){const t=totals(items);return `<aside class="summary"><h2>ORDER SUMMARY</h2>${checkout?items.map(x=>{const p=PRODUCTS.find(p=>p.id===x.id);return `<div class="summary-line"><span>${p.name}<br><span class="muted">${x.size} · Qty ${x.qty}</span></span><span>${money(p.price*x.qty)}</span></div>`;}).join(''):''}<div class="summary-line"><span>Subtotal</span><span>${money(t.subtotal)}</span></div><div class="summary-line"><span>Shipping</span><span>${t.shipping?money(t.shipping):'Free'}</span></div><div class="summary-line"><span>Tax (demo)</span><span>${money(0)}</span></div><div class="summary-line total"><span>Total</span><span>${money(t.total)}</span></div><p class="small muted">USD · ${t.subtotal<75?`${money(75-t.subtotal)} away from free shipping.`:'Your shipping is on us.'}</p>${checkout?'':'<a class="button lime" href="?page=checkout">Continue to checkout →</a>'}<p class="small muted">Demo checkout. No payment will be collected.</p></aside>`;}
function cartPage(){return `<main class="page"><div class="breadcrumb"><a href="?page=home">Home</a> / Your bag</div><h1>YOUR BAG.</h1>${!cart.length?'<div class="empty"><h2>ROOM FOR YOUR NEXT MOVE.</h2><p>Your bag is empty. Find something that moves with you.</p><a class="button lime" href="?page=shop">Explore the essentials →</a></div>':`<div class="cart-layout"><div>${cart.map((x,i)=>{const p=PRODUCTS.find(p=>p.id===x.id);return `<article class="cart-row"><a href="${url('product',{id:p.id})}"><img src="${p.image}" alt="${p.name}"></a><div><a href="${url('product',{id:p.id})}"><h3>${p.name}</h3></a><p>${p.color} / ${x.size}</p><div class="quantity"><button data-qty="${i}" data-delta="-1" aria-label="Decrease ${p.name} quantity" ${x.qty===1?'disabled':''}>−</button><span>${x.qty}</span><button data-qty="${i}" data-delta="1" aria-label="Increase ${p.name} quantity" ${x.qty===99?'disabled':''}>+</button></div><button class="remove" data-remove="${i}">Remove</button></div><span class="price">${money(p.price*x.qty)}</span></article>`;}).join('')}<a class="text-link" style="display:inline-block;margin-top:25px" href="?page=shop">← Continue shopping</a></div>${summary(cart)}</div>`}</main>`;}
function checkoutItems(params){if(params.get('mode')==='buy'){const p=PRODUCTS.find(p=>p.id===params.get('id')),size=params.get('size'),qty=Number(params.get('qty'));return p&&p.sizes.includes(size)&&Number.isInteger(qty)&&qty>0&&qty<=5?[{id:p.id,size,qty}]:[];}return cart;}
const field = (name,label,value='',type='text',full=false,extra='')=>`<label class="field ${full?'full':''}">${label}<input name="${name}" type="${type}" value="${escapeHTML(value)}" required maxlength="160" ${extra}></label>`;
function checkout(params){const items=checkoutItems(params),u=currentUser||{};if(!items.length)return `<main class="page empty"><h1>NOTHING TO CHECK OUT YET.</h1><a class="button" href="?page=shop">Explore essentials</a></main>`;return `<main class="page"><div class="breadcrumb"><a href="?page=cart">Your bag</a> / Checkout</div><h1>ONE MORE MOVE.</h1><div class="checkout-layout"><form id="checkout-form" class="checkout-form"><div class="notice">This is a demo checkout. Use fictional details only. No payment or shipment will be made. <button type="button" class="text-link icon-button" id="fill-demo">Use demo details</button></div><h2>CONTACT & SHIPPING</h2><div class="form-grid">${field('email','Email',u.email,'email',true,'autocomplete="email"')}${field('firstName','First name',u.firstName)}${field('lastName','Last name',u.lastName)}${field('phone','Phone',u.phone,'tel',true,'autocomplete="tel"')}${field('address','Street address',u.address,'text',true,'autocomplete="street-address"')}${field('city','City',u.city)}<label class="field">State<select name="state" required><option value="">Select state</option>${'AL AK AZ AR CA CO CT DE DC FL GA HI ID IL IN IA KS KY LA ME MD MA MI MN MS MO MT NE NV NH NJ NM NY NC ND OH OK OR PA RI SC SD TN TX UT VT VA WA WV WI WY'.split(' ').map(s=>`<option ${u.state===s?'selected':''}>${s}</option>`).join('')}</select></label>${field('zip','ZIP code',u.zip,'text',false,'pattern="[0-9]{5}(-[0-9]{4})?" autocomplete="postal-code"')}<label class="field">Country<input name="country" value="United States" readonly></label></div><h2>PAYMENT</h2><div class="notice"><strong>Demo payment</strong><br>Visa ending in 4242 · No card information required.</div><label class="small"><input type="checkbox" required> I understand this is a simulated order.</label><p id="checkout-error" class="error" role="alert"></p><button class="button lime" type="submit">Place demo order ${icon('arrow')}</button></form>${summary(items,true)}</div></main>`;}
const REGISTRATION_STATES = 'AL AK AZ AR CA CO CT DE DC FL GA HI ID IL IN IA KS KY LA ME MD MA MI MN MS MO MT NE NV NH NJ NM NY NC ND OH OK OR PA RI SC SD TN TX UT VT VA WA WV WI WY'.split(' ');
function registrationAddressFields() {
  return `<fieldset class="registration-address"><legend>Address (optional)</legend><p class="small muted">Save an address for checkout, or leave these fields blank.</p><div class="form-grid">
    <label class="field full">Street address (optional)<input name="address" autocomplete="street-address" maxlength="160"></label>
    <label class="field">City (optional)<input name="city" autocomplete="address-level2" maxlength="128"></label>
    <label class="field">State (optional)<select name="state" autocomplete="address-level1"><option value="">Select state</option>${REGISTRATION_STATES.map(state=>`<option>${state}</option>`).join('')}</select></label>
    <label class="field">ZIP code (optional)<input name="zip" autocomplete="postal-code" maxlength="10" pattern="[0-9]{5}(-[0-9]{4})?" title="Use a 5-digit ZIP code or ZIP+4, such as 97205 or 97205-1234"></label>
    <label class="field">Country (optional)<select name="country" autocomplete="country-name"><option value="">Select country</option><option>United States</option></select></label>
  </div></fieldset>`;
}
function registrationAddress(data) {
  const address = { address: (data.address || '').trim(), city: (data.city || '').trim(), state: (data.state || '').trim(), zip: (data.zip || '').trim(), country: (data.country || '').trim() };
  if (address.zip && !/^[0-9]{5}(-[0-9]{4})?$/.test(address.zip)) throw new Error('Enter a valid 5-digit ZIP code or ZIP+4, or leave ZIP code blank.');
  if (address.state && !REGISTRATION_STATES.includes(address.state)) throw new Error('Select a valid US state or leave it blank.');
  if (address.country && address.country !== 'United States') throw new Error('Select United States or leave country blank.');
  if (address.address.length > 160 || address.city.length > 128) throw new Error('Please shorten your street address or city.');
  return address;
}
function account(params){if(currentUser){const u=currentUser;return `<main class="page"><div class="profile"><div class="eyebrow">Motion Club · ${membershipFor(currentUser) ? 'Premium' : 'Basic member'}</div><h1>HEY, ${escapeHTML(u.firstName)}.</h1><p>Your next move starts here.</p>${membershipPortal()}<div class="notice">Demo membership saved on this browser. Use fictional information only.</div><dl>${[['Username',u.username],['Name',`${u.firstName} ${u.lastName}`],['Email',u.email],['Phone',u.phone],['Address',[u.address,u.city,[u.state,u.zip].filter(Boolean).join(' ')].filter(Boolean).join(', ')],['Country',u.country]].map(([k,v])=>`<dt class="muted">${k}</dt><dd>${escapeHTML(v||'Not provided')}</dd>`).join('')}</dl><a class="button lime" href="?page=shop">Keep moving →</a> <button class="button outline" id="logout">Log out</button></div></main>`;}registration=params.get('mode')==='register';return `<main class="page"><div class="form-card"><div class="eyebrow">The Motion Club</div><h1>${registration?'JOIN THE MOVEMENT.':'WELCOME BACK.'}</h1><div class="auth-tabs"><a class="${!registration?'active':''}" href="?page=account">Log in</a><a class="${registration?'active':''}" href="?page=account&mode=register">Create account</a></div><div class="notice">Demo membership only. Accounts stay on this browser. Please use fictional information and a unique demo password.</div><form id="auth-form">${registration?`${field('firstName','First name')}${field('lastName','Last name')}${field('username','Username','','text',false,'pattern="[A-Za-z0-9_]{3,24}" title="3–24 letters, numbers, or underscores"')}${field('email','Email','','email')}`:field('identity','Email or username')}<label class="field">Password<input type="password" name="password" required minlength="8" maxlength="128" autocomplete="${registration?'new-password':'current-password'}"></label>${registration?registrationAddressFields():''}<p id="auth-error" class="error" role="alert"></p><button class="button lime" style="width:100%">${registration?'Create demo account':'Log in'}</button></form><div class="notice" style="margin-top:24px;margin-bottom:0"><strong>Meet your demo member</strong><br>alexmorgan / Motion2026!<br><span class="muted">alex.morgan@example.com</span><button class="button outline" style="width:100%;margin-top:15px" id="demo-login">Explore as Alex Morgan</button></div></div></main>`;}
const MEMBERSHIP_PLANS = Object.freeze({
  monthly: { name: 'Monthly', price: 15, interval: 'month', pixelPlanId: 'premium_monthly' },
  yearly: { name: 'Yearly', price: 120, interval: 'year', pixelPlanId: 'premium_yearly' }
});

function membershipFor(user) {
  if (!user?.username) return null;
  const records = read('nm_memberships', []);
  if (!Array.isArray(records)) return null;
  return records.find(record => record?.username === user.username.toLowerCase()
    && record.tier === 'premium' && record.status === 'active'
    && Object.hasOwn(MEMBERSHIP_PLANS, record.plan)) || null;
}

function subscribeMember(planId) {
  if (!currentUser?.username) throw new Error('Please log in to subscribe.');
  if (!Object.hasOwn(MEMBERSHIP_PLANS, planId)) throw new Error('Please choose a subscription plan.');
  const existing = membershipFor(currentUser);
  if (existing) return existing;
  const plan = MEMBERSHIP_PLANS[planId];
  const subscription = {
    username: currentUser.username.toLowerCase(), tier: 'premium', status: 'active',
    plan: planId, price: plan.price, currency: 'USD', subscribedAt: new Date().toISOString()
  };
  const stored = read('nm_memberships', []);
  const records = Array.isArray(stored) ? stored : [];
  // Persist the canonical, per-member record before showing a successful upgrade.
  try {
    localStorage.setItem('nm_memberships', JSON.stringify([
      ...records.filter(record => record?.username !== subscription.username), subscription
    ]));
  } catch {
    throw new Error('We could not save your subscription. Enable browser storage and try again.');
  }
  currentUser = { ...currentUser, membership: subscription };
  save('nm_session', currentUser);
  const accounts = read('nm_accounts', []);
  if (Array.isArray(accounts)) save('nm_accounts', accounts.map(account =>
    account.username.toLowerCase() === subscription.username ? { ...account, membership: subscription } : account));
  trackPixelSubscriptionCreated(subscription);
  return subscription;
}

function membershipPortal() {
  const membership = membershipFor(currentUser);
  if (membership) {
    const plan = MEMBERSHIP_PLANS[membership.plan];
    return `<section class="membership premium-active" aria-labelledby="membership-heading">
      <div class="membership-top"><span class="tier-badge">PREMIUM</span><span class="small">Active demo subscription</span></div>
      <h2 id="membership-heading">YOU’RE IN PREMIUM.</h2>
      <p>Your Motion Club membership is upgraded.</p>
      <div class="membership-price">${money(plan.price)} <span>/ ${plan.interval}</span></div>
      <p><strong>${plan.name} plan</strong> · USD</p>
      <p class="small">Your tier and plan are saved for this account on this browser, including after logout.</p>
      <p class="small membership-note">Demo subscription only. No payment is taken and no automatic billing occurs.</p>
    </section>`;
  }
  return `<section class="membership" aria-labelledby="membership-heading">
    <div class="membership-top"><span class="tier-badge basic">BASIC MEMBER</span><span class="small muted">Your current tier · Free</span></div>
    <h2 id="membership-heading">MAKE IT PREMIUM.</h2>
    <p>Choose your Motion Club Premium subscription.</p>
    <form id="membership-form">
      <fieldset class="membership-plans"><legend>Choose a plan</legend>
        <label class="membership-plan"><input type="radio" name="plan" value="monthly" required checked><span><strong>Monthly</strong><span class="membership-price">$15 <small>/ month</small></span><span class="small muted">USD · $180 over 12 months</span></span></label>
        <label class="membership-plan"><input type="radio" name="plan" value="yearly" required><span><strong>Yearly <span class="plan-saving">Save $60</span></strong><span class="membership-price">$120 <small>/ year</small></span><span class="small muted">USD · Equivalent to $10 / month</span></span></label>
      </fieldset>
      <p class="small muted">Demo subscription only. No payment is taken and no automatic billing occurs. Your plan stays active on this browser.</p>
      <p id="membership-error" class="error" role="alert"></p>
      <button type="submit" class="button lime">Subscribe to Premium</button>
    </form>
  </section>`;
}

document.addEventListener('submit', event => {
  if (event.target.id !== 'membership-form') return;
  event.preventDefault();
  try {
    subscribeMember(new FormData(event.target).get('plan'));
    render();
    $('#membership-heading')?.setAttribute('tabindex', '-1');
    $('#membership-heading')?.focus();
    toast('Welcome to Premium. Your membership is saved.');
  } catch (error) {
    $('#membership-error').textContent = error.message;
  }
});

function confirmation(){if(!latestOrder)return `<main class="page empty"><h1>NO ORDER YET.</h1><a class="button" href="?page=shop">Start shopping</a></main>`;return `<main class="page"><div class="success"><div class="success-icon">✓</div><div class="eyebrow">Demo order ${escapeHTML(latestOrder.id)}</div><h1>YOU’RE ALL SET.</h1><p>Thanks, ${escapeHTML(latestOrder.firstName)}. Your simulated order is complete.</p><div class="notice">No payment was taken, no email was sent, and no items will ship.</div>${summary(latestOrder.items,true)}<a class="button lime" style="margin-top:25px" href="?page=shop">Keep exploring →</a></div></main>`;}
function render(trackPageView=true,trackProductView=false){const identityReady=syncPixelUser(currentUser);const params=captureURL(),page=params.get('page')||'home';const checkoutSnapshot=page==='checkout'?checkoutItems(params).map(item=>({...item})):[];const views={home,shop:()=>shop(params),product:()=>product(params),cart:cartPage,checkout:()=>checkout(params),account:()=>account(params),confirmation};document.title=`${({home:'Made to move',shop:params.get('category')||'Shop essentials',product:PRODUCTS.find(p=>p.id===params.get('id'))?.name||'Product',cart:'Your bag',checkout:'Checkout',account:'Motion Club',confirmation:'Order complete'})[page]||'Page not found'} | Nano Motion`;$('#app').innerHTML=header(params)+(views[page]?views[page]():'<main class="page empty"><h1>PAGE NOT FOUND.</h1><a class="button" href="?page=home">Back home</a></main>')+footer();return identityReady.then(ready=>{if(trackPageView && ready)trackPixelPageView(params);if(trackProductView && ready)trackPixelProductView(params);if(trackProductView && ready && checkoutSnapshot.length)trackPixelCommerceEvent('checkout_started',checkoutSnapshot,totals(checkoutSnapshot).total);});}
function updateCart(){save('nm_cart',cart);render();}
document.addEventListener('click',e=>{const link=e.target.closest('a');if(link&&link.getAttribute('href')?.startsWith('?')&&!e.ctrlKey&&!e.metaKey&&!e.shiftKey&&e.button===0){e.preventDefault();navigate(link.getAttribute('href'));return;}const b=e.target.closest('button');if(!b)return;if(b.dataset.size){selectedSize=b.dataset.size;document.querySelectorAll('.size').forEach(el=>{el.classList.toggle('selected',el.dataset.size===selectedSize);el.setAttribute('aria-pressed',el.dataset.size===selectedSize);});$('#size-value').textContent=selectedSize;$('#size-error').textContent='';}if(b.dataset.add||b.dataset.buy){const id=b.dataset.add||b.dataset.buy,p=PRODUCTS.find(p=>p.id===id);if(!p.sizes.includes(selectedSize)){$('#size-error').textContent='Please select a size to continue.';return;}const qty=Number($('#product-qty').value);if(b.dataset.buy){navigate(url('checkout',{mode:'buy',id,size:selectedSize,qty}));return;}const existing=cart.find(x=>x.id===id&&x.size===selectedSize);const previousQty=existing?existing.qty:0;if(existing)existing.qty=Math.min(99,existing.qty+qty);else cart.push({id,size:selectedSize,qty});const addedQty=(existing?existing.qty:qty)-previousQty;if(addedQty>0)trackPixelCommerceEvent('items_added',[{id,qty:addedQty}]);updateCart();toast(`${p.name} added to your bag.`);}if(b.dataset.qty!==undefined){const x=cart[Number(b.dataset.qty)];const previousQty=x.qty;x.qty=Math.max(1,Math.min(99,x.qty+Number(b.dataset.delta)));if(x.qty>previousQty)trackPixelCommerceEvent('items_added',[{id:x.id,qty:x.qty-previousQty}]);updateCart();}if(b.dataset.remove!==undefined){cart.splice(Number(b.dataset.remove),1);updateCart();toast('Item removed from your bag.');}if(b.id==='demo-login'){currentUser={...DEMO_USER};save('nm_session',currentUser);syncPixelUser(currentUser);render();toast('Welcome, Alex.');}if(b.id==='logout'){currentUser=null;save('nm_session',null);render();}if(b.id==='fill-demo'){const f=$('#checkout-form');for(const [k,v] of Object.entries(DEMO_USER)){if(f.elements[k])f.elements[k].value=v;}}});
document.addEventListener('change',e=>{const mapping={'category-filter':'category','size-filter':'size','sort-filter':'sort'};if(mapping[e.target.id]){const p=new URLSearchParams(location.search);p.set('page','shop');if(e.target.value)p.set(mapping[e.target.id],e.target.value);else p.delete(mapping[e.target.id]);navigate(`?${p}`);}});
async function passwordHash(password,salt){if(!globalThis.crypto?.subtle)throw new Error('Registration needs HTTPS or localhost. Use the demo member on this preview.');const bytes=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(salt+password));return Array.from(new Uint8Array(bytes)).map(n=>n.toString(16).padStart(2,'0')).join('');}
document.addEventListener('submit',async e=>{const f=e.target;if(!['search-form','auth-form','checkout-form'].includes(f.id))return;e.preventDefault();const data=Object.fromEntries(new FormData(f));if(f.id==='search-form'){navigate(url('shop',data.q.trim()?{q:data.q.trim()}:{}));return;}if(f.id==='auth-form'){const error=$('#auth-error'),button=f.querySelector('button');if(button.disabled)return;button.disabled=true;const creatingAccount=registration;try{let accounts=read('nm_accounts',[]);if(!Array.isArray(accounts))accounts=[];if(creatingAccount){const username=data.username.trim(),email=data.email.trim().toLowerCase();if(!data.firstName.trim()||!data.lastName.trim())throw new Error('Please enter your first and last name.');if(accounts.some(a=>a.username.toLowerCase()===username.toLowerCase()||a.email.toLowerCase()===email)||username.toLowerCase()===DEMO_USER.username||email===DEMO_USER.email)throw new Error('That username or email is already registered.');const addressFields=registrationAddress(data);const salt=crypto.randomUUID();const account={username,email,firstName:data.firstName.trim(),lastName:data.lastName.trim(),...addressFields,salt,hash:await passwordHash(data.password,salt)};accounts.push(account);try{localStorage.setItem('nm_accounts',JSON.stringify(accounts));}catch{throw new Error('We could not save your account. Enable browser storage and try again.');}const {hash,salt:unused,...profile}=account;currentUser=profile;}else{const identity=data.identity.trim().toLowerCase();if((identity===DEMO_USER.username||identity===DEMO_USER.email)&&data.password==='Motion2026!')currentUser={...DEMO_USER};else{const a=accounts.find(a=>a.username.toLowerCase()===identity||a.email.toLowerCase()===identity);if(!a||await passwordHash(data.password,a.salt)!==a.hash)throw new Error('Email, username, or password is incorrect.');const {hash,salt,...profile}=a;currentUser=profile;}}save('nm_session',currentUser);syncPixelUser(currentUser);if(creatingAccount)trackPixelRegistrationCompleted(currentUser);navigate('?page=account');toast('You’re in. Welcome to the Motion Club.');}catch(err){error.textContent=err.message;button.disabled=false;}return;}if(f.id==='checkout-form'){if(f.dataset.placed==='true')return;const items=checkoutItems(new URLSearchParams(location.search));if(!items.length)return;for(const name of ['firstName','lastName','address','city','phone'])if(!data[name]?.trim()){$('#checkout-error').textContent='Please complete all shipping details.';return;}f.dataset.placed='true';latestOrder={id:`NM-${Date.now().toString(36).toUpperCase()}`,firstName:data.firstName.trim(),items:items.map(x=>({...x})),total:totals(items).total};save('nm_last_order',latestOrder);if(currentUser){currentUser={...currentUser,...data};delete currentUser.password;save('nm_session',currentUser);let accounts=read('nm_accounts',[]);if(Array.isArray(accounts)){accounts=accounts.map(a=>a.username===currentUser.username?{...a,...currentUser}:a);save('nm_accounts',accounts);}}trackPixelCommerceEvent('order_created',latestOrder.items,latestOrder.total);if(new URLSearchParams(location.search).get('mode')!=='buy'){cart=[];save('nm_cart',cart);}navigate('?page=confirmation');}});
window.addEventListener('popstate',()=>{selectedSize='';render(true,true);});
render(true,true);
